head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[xml > M > getChildrenByTagName]<br/>XML Element 의 직계 자식 노드 중 지정한 태그명과 일치하는 Element 노드들을 배열로 반환합니다.",
    "validation" : [
        "element(필수) 파라미터로 자식을 검색할 부모 XML Element 노드를 설정할 수 있어야 합니다.",
        "name(필수) 파라미터로 검색할 태그명을 설정할 수 있어야 합니다.",
        "uri(선택) 파라미터로 네임스페이스 URI 를 설정하면 태그명과 URI 가 모두 일치하는 노드만 반환해야 합니다.",
        "일치하는 XML Element 노드들의 배열을 반환해야 합니다.",
        "일치하는 노드가 없으면 빈 배열을 반환해야 합니다.",
        "직계 자식 노드만 검색하며 손자 이하의 노드는 검색하지 않아야 합니다.",
    ]
}

scwin.storeNode = null;

scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // book 하위에 또 book 이 있는 구조 (손자 노드 검색 제외 확인용)
    // ns:item 네임스페이스 노드 포함 (uri 파라미터 확인용)
    var doc = WebSquare.xml.parse(
        "<bookstore xmlns:ns='http://example.com/ns'>" +
            "<book idx='1'><title>Harry Potter</title></book>" +
            "<book idx='2'><title>Learning XML</title><book idx='inner'>inner book</book></book>" +
            "<book idx='3'><title>Clean Code</title></book>" +
            "<magazine>Monthly Tech</magazine>" +
            "<magazine>Weekly News</magazine>" +
            "<ns:item>NS Item 1</ns:item>" +
            "<ns:item>NS Item 2</ns:item>" +
        "</bookstore>"
    );
    scwin.storeNode = WebSquare.xml.findNode(doc, "bookstore");
};



scwin.btn_getChildrenByTagName_onclick = function () {
    let name = par_name.getValue();
    let uri = par_uri.getValue();

    var result;
    if (uri !== '') {
        result = WebSquare.xml.getChildrenByTagName(scwin.storeNode, name, uri);
        wf_body_bottom.getObj("scwin").setReturnValue("getChildrenByTagName(storeNode, '" + name + "', '" + uri + "')");
    } else {
        result = WebSquare.xml.getChildrenByTagName(scwin.storeNode, name);
        wf_body_bottom.getObj("scwin").setReturnValue("getChildrenByTagName(storeNode, '" + name + "')");
    }
    wf_body_bottom.getObj("scwin").setReturnValue("결과 개수 : " + result.length);

    for (var i = 0; i < result.length; i++) {
        var node = result[i];
        var attrs = "";
        for (var j = 0; j < node.attributes.length; j++) {
            attrs += node.attributes[j].name + "=" + node.attributes[j].value + " ";
        }
        wf_body_bottom.getObj("scwin").setReturnValue("[" + i + "] " + node.nodeName + " " + attrs);
    }

    if (result.length === 0) {
        wf_body_bottom.getObj("scwin").setReturnValue("빈 배열 반환 확인");
    }
}
